import React, { useState } from "react";
import axios from "axios";
import "./App.css";

interface SimplifiedResult {
  simplified_explanation: string;
  steps: string[];
  analogy: { text: string; mapping: Array<{ concept: string; analogy: string }> };
  why_explanation: string;
}

interface VerificationResult {
  results: Array<{ claim: string; status: string; evidence: string; confidence: number }>;
  support_score: number;
}

interface QuizQuestion {
  question: string;
  options: string[];
  answer: string;
}

interface FullResult {
  simplified: SimplifiedResult;
  verification: VerificationResult;
  quiz: { questions: QuizQuestion[] };
}

function App() {
  const [text, setText] = useState<string>("");
  const [result, setResult] = useState<FullResult | null>(null);
  const [loading, setLoading] = useState<boolean>(false);
  const [loadingStep, setLoadingStep] = useState<string>("");
  const [selectedAnswers, setSelectedAnswers] = useState<Record<number, string>>({});
  const [showResults, setShowResults] = useState<boolean>(false);

  const processText = async () => {
    if (!text.trim()) return alert("Please enter some text");

    setLoading(true);
    setLoadingStep("Simplifying with Feynman Technique...");
    setSelectedAnswers({});
    setShowResults(false);
    setResult(null);

    try {
      // Step 1: Simplifying
      setLoadingStep("Simplifying with Feynman Technique...");
      await new Promise(resolve => setTimeout(resolve, 800)); // smooth feel

      // Step 2: Processing
      setLoadingStep("Extracting claims and verifying...");

      const res = await axios.post("http://localhost:5000/process", { text });

      setLoadingStep("Generating quiz questions...");
      await new Promise(resolve => setTimeout(resolve, 600));

      setResult(res.data);
    } catch (err: any) {
      alert("Error: " + (err.response?.data?.error || err.message));
    } finally {
      setLoading(false);
      setLoadingStep("");
    }
  };

  const handleAnswerSelect = (questionIndex: number, selectedOption: string) => {
    setSelectedAnswers(prev => ({
      ...prev,
      [questionIndex]: selectedOption
    }));
  };

  const checkAnswers = () => {
    setShowResults(true);
  };

  const totalQuestions = result?.quiz.questions.length ?? 0;
  const answeredQuestions = Object.keys(selectedAnswers).length;
  const correctAnswers =
    showResults && result
      ? result.quiz.questions.reduce((count, q, index) => {
          const selected = selectedAnswers[index];
          return selected === q.answer ? count + 1 : count;
        }, 0)
      : 0;

  return (
    <div className="app-shell">
      <div className="ambient ambient-one" />
      <div className="ambient ambient-two" />

      <main className="app-container">
        <header className="hero" data-animate="fade-up">
          <span className="hero-chip">AI Learning Studio</span>
          <h1>Feynman AI Playground</h1>
          <p>Simplify hard topics, verify each claim, and test your understanding instantly.</p>
        </header>

        <section className="glass-card input-card" data-animate="fade-up" style={{ animationDelay: "120ms" }}>
          <div className="section-head">
            <h2>Your Source Text</h2>
            <span className="section-note">Best with academic or technical content</span>
          </div>

          <textarea
            rows={9}
            className="source-textarea"
            placeholder="Paste your academic text here..."
            value={text}
            onChange={(e) => setText(e.target.value)}
          />

          <button onClick={processText} disabled={loading} className="primary-btn">
            {loading ? `Processing: ${loadingStep || "Working..."}` : "Simplify, Verify and Build Quiz"}
          </button>
        </section>

        {result && (
          <div className="results-grid">
            <section className="glass-card" data-animate="fade-up" style={{ animationDelay: "180ms" }}>
              <div className="section-head">
                <h2>Simplified Explanation</h2>
              </div>

              <p className="lead-copy">{result.simplified.simplified_explanation}</p>

              <h3>Steps</h3>
              <ol className="step-list">
                {result.simplified.steps.map((step, i) => (
                  <li key={i}>{step}</li>
                ))}
              </ol>

              <h3>Analogy</h3>
              <p className="analogy-copy">{result.simplified.analogy.text}</p>

              <h3>Why It Works</h3>
              <p className="muted-copy">{result.simplified.why_explanation}</p>
            </section>

            <section className="glass-card" data-animate="fade-up" style={{ animationDelay: "240ms" }}>
              <div className="section-head">
                <h2>Verification Results</h2>
                <span
                  className={`score-pill ${
                    result.verification.support_score >= 80 ? "good" : "risk"
                  }`}
                >
                  Support Score: {result.verification.support_score}%
                </span>
              </div>

              <div className="table-wrap">
                <table className="result-table">
                  <thead>
                    <tr>
                      <th>Claim</th>
                      <th>Status</th>
                      <th>Evidence</th>
                    </tr>
                  </thead>
                  <tbody>
                    {result.verification.results.map((r, i) => (
                      <tr key={i}>
                        <td>{r.claim}</td>
                        <td>
                          <span
                            className={`status-tag ${
                              r.status === "SUPPORTED"
                                ? "supported"
                                : r.status === "CONTRADICTED"
                                  ? "contradicted"
                                  : "partial"
                            }`}
                          >
                            {r.status}
                          </span>
                        </td>
                        <td className="evidence-cell">{r.evidence}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </section>

            <section className="glass-card" data-animate="fade-up" style={{ animationDelay: "300ms" }}>
              <div className="section-head">
                <h2>Quiz Arena</h2>
                <span className="section-note">
                  {answeredQuestions}/{totalQuestions} answered
                </span>
              </div>

              {showResults && (
                <p className="quiz-score">
                  You scored <strong>{correctAnswers}</strong> out of <strong>{totalQuestions}</strong>
                </p>
              )}

              {result.quiz.questions.map((q, index) => {
                const userAnswer = selectedAnswers[index];
                const correctAnswer = q.answer;
                const isCorrect = userAnswer === correctAnswer;

                return (
                  <article
                    key={index}
                    className="quiz-card"
                    style={{ animationDelay: `${index * 80}ms` }}
                  >
                    <p className="quiz-question">
                      {index + 1}. {q.question}
                    </p>

                    <div className="option-list">
                      {q.options.map((option, i) => {
                        const optionLetter = option.charAt(0);
                        const isSelected = userAnswer === optionLetter;
                        const isRightAnswer = optionLetter === correctAnswer;

                        const stateClass = showResults
                          ? isRightAnswer
                            ? "correct"
                            : isSelected
                              ? "wrong"
                              : "neutral"
                          : isSelected
                            ? "selected"
                            : "neutral";

                        return (
                          <button
                            key={i}
                            onClick={() => !showResults && handleAnswerSelect(index, optionLetter)}
                            className={`option-btn ${stateClass}`}
                            disabled={showResults}
                          >
                            <span>{option}</span>
                            {showResults && isRightAnswer && <strong>Correct</strong>}
                            {showResults && isSelected && !isRightAnswer && <strong>Incorrect</strong>}
                          </button>
                        );
                      })}
                    </div>

                    {showResults && !isCorrect && (
                      <p className="answer-note">
                        Correct answer: <strong>{correctAnswer}</strong>
                      </p>
                    )}
                  </article>
                );
              })}

              {!showResults && answeredQuestions > 0 && (
                <button onClick={checkAnswers} className="secondary-btn success">
                  Check My Answers
                </button>
              )}

              {showResults && (
                <button
                  onClick={() => {
                    setShowResults(false);
                    setSelectedAnswers({});
                  }}
                  className="secondary-btn"
                >
                  Try Quiz Again
                </button>
              )}
            </section>
          </div>
        )}
      </main>
    </div>
  );
}

export default App;
